import{_ as t,o as n,c as a,a3 as o}from"./chunks/framework.BTQ4eCVb.js";const h=JSON.parse('{"title":"Accounting — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Accounting — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/accounting"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Accounting — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/accounting"}]]},"headers":[],"relativePath":"user-guide/accounting.md","filePath":"user-guide/accounting.md","lastUpdated":1788612600000}'),r={name:"user-guide/accounting.md"};function s(l,e,i,c,d,u){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="accounting-—-user-guide" tabindex="-1">Accounting — User Guide <a class="header-anchor" href="#accounting-—-user-guide" aria-label="Permalink to &quot;Accounting — User Guide&quot;">​</a></h1><p>Enable <strong>Accounting</strong> from Marketplace (free). Nav appears under <strong>Finance</strong>: Accounts, Journals, Transfers, General Ledger.</p><h2 id="chart-of-accounts" tabindex="-1">Chart of accounts <a class="header-anchor" href="#chart-of-accounts" aria-label="Permalink to &quot;Chart of accounts&quot;">​</a></h2><ol><li>Open <strong>Accounts</strong>. A starter chart loads automatically the first time. Each row shows its <strong>current balance</strong> (from posted journals).</li><li>Use <strong>New account</strong> to add custom codes (code, name, type). Optionally set a <strong>parent</strong> account for hierarchy, and tick <strong>Header</strong> for non-postable grouping rows (headers cannot appear on journal lines).</li><li>For bank or cash wallets, set type <strong>Asset</strong> and tick <strong>Cash or bank account</strong>. Starter <strong>Cash (<code>1000</code>)</strong> is already cash/bank; add more banks the same way.</li><li>Starter chart also includes Tax Payable (<code>2100</code>) and Retained Earnings (<code>3100</code>). System accounts cannot be deleted or renumbered; accounts with posted journal lines cannot be deleted.</li><li>Soft-deleted custom accounts can be restored (or permanently deleted) via the trash filter when you have restore / force-delete permission.</li></ol><h2 id="opening-balances-trial-balance" tabindex="-1">Opening balances (trial balance) <a class="header-anchor" href="#opening-balances-trial-balance" aria-label="Permalink to &quot;Opening balances (trial balance)&quot;">​</a></h2><p>To load a full opening trial balance (not just one cash/bank account):</p><ol><li>Open <strong>Accounts</strong> → <strong>Opening balances</strong> (<code>/accounts/opening-balances</code>).</li><li>Enter a date and balanced debit/credit lines across postable accounts (headers are excluded).</li><li>Saving posts one multi-line opening journal. Debits must equal credits.</li></ol><h2 id="set-balance-cash-bank" tabindex="-1">Set balance (cash &amp; bank) <a class="header-anchor" href="#set-balance-cash-bank" aria-label="Permalink to &quot;Set balance (cash &amp; bank)&quot;">​</a></h2><p>Balances are never edited as a stored field. On an active cash/bank account:</p><ol><li>Open the account → <strong>Set balance</strong>.</li><li>Enter the <strong>target</strong> amount and date. Offset defaults to <strong>Owner Equity (<code>3000</code>)</strong>; you can pick another active account.</li><li>Saving posts a journal for the <strong>difference</strong> only (<code>ADJ-</code> number). Increase: Dr cash/bank / Cr offset. Decrease: Dr offset / Cr cash/bank.</li><li>Recent adjustments appear under <strong>Balance adjustments</strong> on the account. <strong>Void</strong> reverses the linked journal (requires <code>accounting.void</code>).</li></ol><h2 id="journals" tabindex="-1">Journals <a class="header-anchor" href="#journals" aria-label="Permalink to &quot;Journals&quot;">​</a></h2><ol><li>Open <strong>Journals</strong> → <strong>New journal</strong>.</li><li>Set the entry date and memo.</li><li>Add at least two lines on the classic <strong>Account / Debit / Credit / Memo</strong> grid. Each line needs an account and either a debit or a credit (not both). Zero Dr/Cr cells stay blank; amounts use currency formatting.</li><li>Debits must equal credits before you can save. The list shows an <strong>Amount</strong> column for each entry.</li><li>Open the entry → <strong>Post</strong> to make it immutable and visible on the general ledger.</li><li>Posted entries can be <strong>Void</strong> (excluded from GL/reports; reason optional).</li></ol><h2 id="transfers" tabindex="-1">Transfers <a class="header-anchor" href="#transfers" aria-label="Permalink to &quot;Transfers&quot;">​</a></h2><p>Move money between cash/bank accounts without treating it as income or expense:</p><ol><li>Open <strong>Transfers</strong> → <strong>New transfer</strong>.</li><li>Choose <strong>From</strong> and <strong>To</strong> (both must be cash/bank), amount, date, optional reference/memo.</li><li>Saving posts a journal immediately (Dr destination / Cr source) and updates both balances.</li><li>Open a transfer → <strong>Void</strong> to reverse the journal (reason optional).</li></ol><h2 id="invoices-credit-notes-when-those-modules-are-installed" tabindex="-1">Invoices &amp; credit notes (when those modules are installed) <a class="header-anchor" href="#invoices-credit-notes-when-those-modules-are-installed" aria-label="Permalink to &quot;Invoices &amp; credit notes (when those modules are installed)&quot;">​</a></h2><p>When Accounting is entitled:</p><ul><li><strong>Invoices — Send</strong>: posts Dr Accounts Receivable (<code>1100</code>) / Cr Sales Revenue (<code>4000</code>) for the invoice total; links the journal on the invoice. <strong>Cancel</strong> voids that journal.</li><li><strong>Credit Notes — Apply</strong>: posts Dr Sales Revenue / Cr Accounts Receivable for the credit total; links the journal (applied credits stay irreversible).</li><li>No backfill for invoices or credits issued before Accounting was installed.</li></ul><h2 id="payments-expenses-when-those-modules-are-installed" tabindex="-1">Payments &amp; expenses (when those modules are installed) <a class="header-anchor" href="#payments-expenses-when-those-modules-are-installed" aria-label="Permalink to &quot;Payments &amp; expenses (when those modules are installed)&quot;">​</a></h2><ul><li><strong>Payments</strong>: choose <strong>Deposit to</strong> (cash/bank). On <strong>Post</strong>, Accounting creates Dr deposit / Cr Accounts Receivable (settles the receivable booked on invoice send).</li><li><strong>Expenses</strong>: on <strong>Mark as paid</strong>, choose <strong>Paid from</strong> (cash/bank) and optionally an expense P&amp;L account (defaults to Operating Expenses). Accounting creates Dr expense / Cr paid-from.</li></ul><h2 id="general-ledger" tabindex="-1">General ledger <a class="header-anchor" href="#general-ledger" aria-label="Permalink to &quot;General ledger&quot;">​</a></h2><ol><li>Open <strong>General Ledger</strong>.</li><li>Optionally filter by account and date range → <strong>Apply filters</strong>.</li><li>Review opening/closing balance and paginated line detail for posted journals only. Amounts are currency-formatted; journal numbers link to the entry.</li><li>Use <strong>Export CSV</strong> to download the filtered ledger.</li></ol><h2 id="related-reports" tabindex="-1">Related reports <a class="header-anchor" href="#related-reports" aria-label="Permalink to &quot;Related reports&quot;">​</a></h2><p>Install <strong>Financial Reports</strong> (requires Accounting) for Trial Balance, Profit &amp; Loss, and Balance Sheet.</p>',24)])])}const p=t(r,[["render",s]]);export{h as __pageData,p as default};
